// --- CONFIGURAÇÕES DO SISTEMA ---
const VALOR_ALVO = 23;        // Temperatura padrão da sala (23°C)
const PORCENTAGEM_ERRO = 30;  // Tolerância de erro (30% cobre de ~16°C até ~30°C)
// ------------------------------------

// Inicializa as variáveis de contexto
let leituras = context.get('leituras') || [];
let bloqueado = context.get('bloqueado') || false;

// 1. VERIFICAÇÃO DE BLOQUEIO
// Se o tempo já expirou (20 leituras feitas), ignora as novas mensagens
if (bloqueado) {
    node.status({fill:"red", shape:"dot", text: "Bloqueado: Janela de 10min encerrada"});
    return null; 
}

// Captura e valida a temperatura que veio do MQTT
let tempAtual = Number(msg.payload);
if (isNaN(tempAtual)) {
    node.warn("Valor recebido não é um número válido: " + msg.payload);
    return null;
}

// 2. ACUMULAÇÃO DE DADOS
leituras.push(tempAtual);

// Se ainda não chegou a 20 leituras, salva e espera a próxima
if (leituras.length < 20) {
    context.set('leituras', leituras);
    node.status({fill:"blue", shape:"dot", text: `Coletando: ${leituras.length}/20 (Faltam ${(20 - leituras.length) * 30}s)`});
    return null; // Não envia mensagem ainda
}

// 3. ATINGIU OS 10 MINUTOS (20 Leituras) -> TRAVA O FLUXO E CALCULA
bloqueado = true;
context.set('bloqueado', bloqueado);
context.set('leituras', leituras); // Salva o histórico final

// --- CÁLCULO DA MEDIANA ---
let valoresOrdenados = [...leituras].sort((a, b) => a - b);
let metade = Math.floor(valoresOrdenados.length / 2);
let mediana = (valoresOrdenados[metade - 1] + valoresOrdenados[metade]) / 2; // Como são 20 elementos (par), faz a média dos dois centrais

// --- VERIFICAÇÃO DA MARGEM DE ERRO ---
let limiteInferior = VALOR_ALVO * (1 - PORCENTAGEM_ERRO / 100);
let limiteSuperior = VALOR_ALVO * (1 + PORCENTAGEM_ERRO / 100);

let statusErro = "";
let dentroDoLimite = false;

if (mediana < limiteInferior) {
    statusErro = "Abaixo do limite permitido (Para menos)";
} else if (mediana > limiteSuperior) {
    statusErro = "Acima do limite permitido (Para mais)";
} else {
    statusErro = "Dentro do limite aceitável";
    dentroDoLimite = true;
}

// --- MONTAGEM DO PAYLOAD DE SAÍDA ---
msg.payload = {
    resultado: "Janela de 10 minutos concluída. Sistema Bloqueado.",
    totalLeituras: leituras.length,
    medianaCalculada: Number(mediana.toFixed(2)) + "°C",
    valorAlvo: VALOR_ALVO + "°C",
    limitesAceitaveis: {
        min: Number(limiteInferior.toFixed(2)) + "°C",
        max: Number(limiteSuperior.toFixed(2)) + "°C"
    },
    dentroDoLimite: dentroDoLimite,
    status: statusErro,
    historicoDasLeituras: leituras
};

node.status({fill:"red", shape:"dot", text: "Finalizado & Bloqueado"});
return msg;
